//! `COMPD_CS` whose `VERT_CS` has datum type 2002 (ellipsoidal height), read as PROJ's
//! `CompoundCRS::createLax` does: the horizontal CRS goes through `CRS::promoteTo3D`, which drops
//! its identifier for a `Promoted to 3D from` remark and keeps the name of the projected CRS.
//! Expected WKT2_2019 comes from C PROJ 9.9.0 (`proj_create`, `proj_as_wkt`, `MULTILINE=NO`).

use proj_rs::iso19111::create_from_user_input;
use proj_rs::unstable::Crs;
use proj_rs::{DatabaseContext, WktConvention, WktFormatter, WktLines};

fn read(wkt: &str) -> Crs {
    let db = DatabaseContext::create().expect("proj.db");
    create_from_user_input(wkt, &db).expect("COMPD_CS")
}

fn wkt2_2019(crs: &Crs) -> String {
    let mut formatter = WktFormatter::create(WktConvention::Wkt2_2019);
    formatter.set_lines(WktLines::Single);
    crs.export_to_wkt(&mut formatter).expect("WKT2_2019")
}

