/// `GetAuthorityCode()` of GDAL reads the source of the bound CRS: no identifier after promotion.
#[test]
fn promoted_projected_crs_has_no_identifier() {
    let Crs::Bound(bound) = read(COMPD_2002_GDAL) else {
        panic!("bound CRS expected");
    };
    assert_eq!(bound.name(), "NAD83 / Alabama West");
    assert_eq!(bound.source_crs().name(), "NAD83 / Alabama West");
    assert!(bound.source_crs().identifiers().is_empty());
}

/// `CartesianCS::create` refuses a height in feet beside axes in metres, as C PROJ does.
#[test]
fn height_unit_must_match_projected_axes() {
    let db = DatabaseContext::create().expect("proj.db");
    assert!(create_from_user_input(COMPD_2002_FOOT, &db).is_err());
}

const COMPD_2002_GDAL: &str = r#"COMPD_CS["X + h",PROJCS["NAD83 / Alabama West",GEOGCS["NAD83",DATUM["North_American_Datum_1983",SPHEROID["GRS 1980",6378137,298.257222101,AUTHORITY["EPSG","7019"]],TOWGS84[0,0,0,0,0,0,0],AUTHORITY["EPSG","6269"]],PRIMEM["Greenwich",0,AUTHORITY["EPSG","8901"]],UNIT["degree",0.0174532925199433,AUTHORITY["EPSG","9122"]],AUTHORITY["EPSG","4269"]],PROJECTION["Transverse_Mercator"],PARAMETER["latitude_of_origin",30],PARAMETER["central_meridian",-87.5],PARAMETER["scale_factor",0.999933333],PARAMETER["false_easting",600000],PARAMETER["false_northing",0],UNIT["metre",1,AUTHORITY["EPSG","9001"]],AXIS["X",EAST],AXIS["Y",NORTH],AUTHORITY["EPSG","26930"]],VERT_CS["Ellipsoidal height",VERT_DATUM["Ellipsoid",2002],UNIT["metre",1],AXIS["Up",UP]]]"#;

const COMPD_2002_FOOT: &str = r#"COMPD_CS["X + h",PROJCS["NAD83 / Alabama West",GEOGCS["NAD83",DATUM["North_American_Datum_1983",SPHEROID["GRS 1980",6378137,298.257222101,AUTHORITY["EPSG","7019"]],TOWGS84[0,0,0,0,0,0,0],AUTHORITY["EPSG","6269"]],PRIMEM["Greenwich",0,AUTHORITY["EPSG","8901"]],UNIT["degree",0.0174532925199433,AUTHORITY["EPSG","9122"]],AUTHORITY["EPSG","4269"]],PROJECTION["Transverse_Mercator"],PARAMETER["latitude_of_origin",30],PARAMETER["central_meridian",-87.5],PARAMETER["scale_factor",0.999933333],PARAMETER["false_easting",600000],PARAMETER["false_northing",0],UNIT["metre",1,AUTHORITY["EPSG","9001"]],AXIS["X",EAST],AXIS["Y",NORTH],AUTHORITY["EPSG","26930"]],VERT_CS["Ellipsoidal height",VERT_DATUM["Ellipsoid",2002],UNIT["foot",0.3048],AXIS["Up",UP]]]"#;
